(()=>{'use strict';const qs=window.EXAM_BANK;const el=id=>document.getElementById(id);const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const chapter=el('chapter'),type=el('type'),search=el('search'),list=el('questions');const chapters=[...new Map(qs.map(q=>[q.chapter,q.chapterTitle]))];chapter.insertAdjacentHTML('beforeend',chapters.map(([id,title])=>`<option value="${id}">${escape(title)}</option>`).join(''));const kinds=[...new Set(qs.map(q=>q.type))];type.insertAdjacentHTML('beforeend',kinds.map(k=>`<option>${escape(k)}</option>`).join(''));function render(){const wrong=GISStudy.read().wrong,needle=search.value.trim().toLowerCase(),filtered=qs.filter(q=>(!el('wrongOnly').checked||wrong[q.id])&&(!chapter.value||q.chapter===Number(chapter.value))&&(!type.value||q.type===type.value)&&(!needle||[q.question,q.answer,...q.options].join(' ').toLowerCase().includes(needle)));el('count').textContent=`显示 ${filtered.length} / ${qs.length} 题`;el('empty').hidden=filtered.length!==0;list.innerHTML=filtered.map(q=>{const options=q.options.length?q.options.map((s,i)=>[String.fromCharCode(65+i),s]):q.type==='判断并说明'?[['正确','正确'],['错误','错误']]:[];return `<article class="exam-question"><div class="exam-meta"><span>${escape(q.chapterTitle)} · 第 ${q.id.split('-')[1]} 题</span><span>${escape(q.type)}</span>${wrong[q.id]?`<button type="button" data-remove-wrong="${q.id}">移出错题本</button>`:""}</div><h2>${escape(q.question)}</h2>${options.length?`<fieldset><legend>请选择答案</legend>${options.map(([v,label])=>`<label class="option"><input type="radio" name="answer-${q.id}" value="${escape(v)}"><span>${q.options.length?escape(v)+'. ':''}${escape(label)}</span></label>`).join('')}</fieldset><button class="check" type="button" data-check="${q.id}">检查答案</button><span class="feedback" id="feedback-${q.id}" aria-live="polite"></span>`:''}<details><summary>查看参考答案与解析</summary><div class="answer">${q.options.length?'参考选项：'+escape(q.correct)+'。':''}${escape(q.answer)}</div></details></article>`}).join('')};list.addEventListener('click',event=>{const remove=event.target.closest('[data-remove-wrong]');if(remove){const data=GISStudy.read();delete data.wrong[remove.dataset.removeWrong];GISStudy.write(data);render();return}const button=event.target.closest('[data-check]');if(!button)return;const q=qs.find(x=>x.id===button.dataset.check),selected=list.querySelector(`input[name="answer-${q.id}"]:checked`),feedback=el('feedback-'+q.id);if(selected&&selected.value!==q.correct){const data=GISStudy.read();data.wrong[q.id]=true;GISStudy.write(data)}feedback.textContent=!selected?'请先选择一个答案。':selected.value===q.correct?'回答正确。':'回答有误，已加入错题本，可展开答案查看解析。'});[chapter,type,el('wrongOnly')].forEach(x=>x.addEventListener('change',render));search.addEventListener('input',render);el('reset').addEventListener('click',()=>{chapter.value='';type.value='';search.value='';el('wrongOnly').checked=false;render()});el('showAnswers').addEventListener('click',()=>list.querySelectorAll('details').forEach(x=>x.open=true));el('hideAnswers').addEventListener('click',()=>list.querySelectorAll('details').forEach(x=>x.open=false));render()})();
